arguments.file_text:
@page "/apply"
@rendermode InteractiveServer
@using sv_6f0f407af4bd4aecb281412caa5ddf1c.Models
@using sv_6f0f407af4bd4aecb281412caa5ddf1c.Services
@using sv_6f0f407af4bd4aecb281412caa5ddf1c.Components.Pages.ApplySteps
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2 class="mb-4">Job Application</h2>

    @if (!_submitted)
    {
        <!-- Step Indicator -->
        <nav class="step-indicator mb-4" aria-label="Application steps">
            @for (int i = 0; i < _stepNames.Length; i++)
            {
                var stepIndex = i;
                var status = GetStepStatus(stepIndex);
                <button class="step-item @status"
                        disabled="@(status == "future")"
                        @onclick="() => GoToStep(stepIndex)"
                        aria-current="@(stepIndex == _currentStep ? "step" : null)">
                    <span class="step-circle">
                        @if (status == "completed")
                        {
                            <span class="step-check">✓</span>
                        }
                        else
                        {
                            @(stepIndex + 1)
                        }
                    </span>
                    <span class="step-label">@_stepNames[stepIndex]</span>
                </button>
                @if (stepIndex < _stepNames.Length - 1)
                {
                    <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
                }
            }
        </nav>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="alert alert-danger" role="alert">@_errorMessage</div>
        }

        <!-- Step Content -->
        @switch (_currentStep)
        {
            case 0:
                <StepPersonalInfo Model="_personalInfo"
                                  OnNext="HandlePersonalInfoNext" />
                break;
            case 1:
                <StepWorkHistory Entries="_workEntries"
                                 OnBack="GoBack"
                                 OnNext="GoNext" />
                break;
            case 2:
                <StepReferences References="_references"
                                OnBack="GoBack"
                                OnNext="GoNext" />
                break;
            case 3:
                <StepCoverLetter @bind-CoverLetter="_coverLetter"
                                 OnBack="GoBack"
                                 OnNext="GoNext" />
                break;
            case 4:
                <StepReview PersonalInfo="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            IsSubmitting="_isSubmitting"
                            OnEdit="GoToStep"
                            OnBack="GoBack"
                            OnSubmit="HandleSubmit" />
                break;
        }
    }
    else
    {
        <div class="text-center py-5">
            <div class="confirmation-icon mb-3">✓</div>
