toolArgs.file_text:
.apply-container {
    max-width: 800px;
    margin: 0 auto;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0;
    flex-wrap: wrap;
    padding: 1rem 0;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.25rem 0.5rem;
    min-width: 80px;
    transition: opacity 0.2s;
}

    .step-item:disabled {
        cursor: default;
    }

    .step-item.future {
        opacity: 0.4;
    }

    .step-item.active .step-circle {
        background-color: #0d6efd;
        color: white;
        box-shadow: 0 0 0 3px rgba(13, 110, 253, 0.25);
    }

    .step-item.completed .step-circle {
        background-color: #198754;
        color: white;
    }

    .step-item.completed:hover .step-circle {
        box-shadow: 0 0 0 3px rgba(25, 135, 84, 0.25);
    }

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background-color: #dee2e6;
    color: #6c757d;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.875rem;
    margin-bottom: 0.375rem;
    transition: all 0.2s;
}

.step-check {
    font-size: 1rem;
}

.step-label {
    font-size: 0.75rem;
    font-weight: 500;
    color: #495057;
    text-align: center;
    white-space: nowrap;
}

.step-connector {
    flex: 1;
    height: 2px;
    background-color: #dee2e6;
    min-width: 20px;
    max-width: 60px;
    align-self: flex-start;
    margin-top: 18px;
    transition: background-color 0.2s;
}

    .step-connector.completed {
        background-color: #198754;
    }

/* Confirmation */
.confirmation-icon {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background-color: #198754;
    color: white;
    font-size: 2.5rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

