@using sv_6f0f407af4bd4aecb281412caa5ddf1c.Models

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-3">Work History</h4>

        @for (int i = 0; i < Entries.Count; i++)
        {
            var index = i;
            var entry = Entries[index];

            <div class="border rounded p-3 mb-3 position-relative">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h6 class="mb-0">Position @(index + 1)</h6>
                    @if (Entries.Count > 1)
                    {
                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveEntry(index)">Remove</button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Company Name</label>
                        <input type="text" class="form-control" @bind="entry.Company" placeholder="Acme Corp" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Job Title</label>
                        <input type="text" class="form-control" @bind="entry.Title" placeholder="Software Engineer" />
                    </div>
                </div>

                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date</label>
                        <input type="date" class="form-control" @bind="entry.StartDate" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end mb-1">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" id="current-@index" @bind="entry.IsCurrent" />
                            <label class="form-check-label" for="current-@index">I currently work here</label>
                        </div>
                    </div>
                </div>

                <div class="mb-0">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" @bind="entry.Description" rows="2" placeholder="Describe your role and responsibilities..."></textarea>
                </div>
            </div>
        }

        <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
            + Add Another Position
        </button>

        <div class="d-flex justify-content-between">
            <button class="btn btn-outline-secondary" @onclick="OnBack">← Back</button>
            <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private string? _error;

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        // Require at least one entry with company and title
        var hasValid = Entries.Any(e => !string.IsNullOrWhiteSpace(e.Company) && !string.IsNullOrWhiteSpace(e.Title));
        if (!hasValid)
        {
            _error = "Please fill in at least one work entry with company name and job title.";
            return;
        }
        _error = null;
        await OnNext.InvokeAsync();
    }
}

@using sv_6f0f407af4bd4aecb281412caa5ddf1c.Models

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-3">References</h4>
        <p class="text-muted">Please provide 2–3 professional references.</p>

        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            var reference = References[index];

            <div class="border rounded p-3 mb-3">
                <div class="d-flex justify-content-between align-items-center mb-2">
                    <h6 class="mb-0">Reference @(index + 1)</h6>
                    @if (References.Count > 2)
                    {
                        <button class="btn btn-sm btn-outline-danger" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>

                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Name</label>
                        <input type="text" class="form-control" @bind="reference.Name" placeholder="Jane Smith" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Relationship</label>
                        <input type="text" class="form-control" @bind="reference.Relationship" placeholder="Former Manager" />
                    </div>
                </div>

                <div class="row">
                    <div class="col-md-6">
                        <label class="form-label">Email</label>
                        <input type="email" class="form-control" @bind="reference.Email" placeholder="jane@example.com" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone</label>
                        <input type="tel" class="form-control" @bind="reference.Phone" placeholder="(555) 987-6543" />
                    </div>
                </div>
            </div>
        }

        @if (References.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                + Add Reference
            </button>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-outline-secondary" @onclick="OnBack">← Back</button>
            <button class="btn btn-primary" @onclick="OnNext">Next →</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }

    private void AddReference()
